/* @motion
[Attendees expand] attendees panel, card height
--acc-expand: Expand duration
--acc-collapse: Collapse duration
--acc-ease: Easing
more --acc-chevron: Chevron flip
[Decline] decline button label and color
--text-morph-dur: Duration
--text-morph-resize-dur: Width duration
--text-morph-ease: Easing
more --text-morph-blur: Blur
more --decline-dur: Color duration
more [Avatar hover] attendee avatars
--avatar-lift: Lift
--avatar-dur: Duration
--avatar-ease-out: Return easing
more --avatar-scale: Scale
more --avatar-falloff: Falloff
more --avatar-ease-in: Hover easing
more [Join call label] join button text
--text-swap-dur: Duration
--text-swap-ease: Easing
--text-swap-translate-y: Distance
more --text-swap-blur: Blur
more [Directions hover] link chevron
--learn-shift: Shift
--learn-in: Duration in
more --learn-out: Duration out
more --learn-spread: Spread
more --learn-ease: Easing
more [Button press] buttons
--press-scale: Scale
--press-dur: Duration
more [Shared scale] global tokens
--ease-smooth-out: Easing
*/

:root {
  --acc-expand: 250ms;
  --acc-collapse: 250ms;
  --acc-chevron: 250ms;
  --acc-ease: cubic-bezier(0.22, 1, 0.36, 1);

  --text-morph-dur: 180ms;
  --text-morph-resize-dur: 240ms;
  --text-morph-blur: 2px;
  --text-morph-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --decline-dur: 150ms;

  --avatar-lift: -4px;
  --avatar-dur: 320ms;
  --avatar-scale: 1.05;
  --avatar-falloff: 0.45;
  --avatar-ease-in: cubic-bezier(0.22, 1, 0.36, 1);
  --avatar-ease-out: cubic-bezier(0.34, 3.85, 0.64, 1);

  --text-swap-dur: 150ms;
  --text-swap-translate-y: 4px;
  --text-swap-blur: 2px;
  --text-swap-ease: ease-in-out;

  --learn-shift: 2px;
  --learn-spread: 8deg;
  --learn-in: 350ms;
  --learn-out: 350ms;
  --learn-ease: cubic-bezier(0.22, 1, 0.36, 1);

  --press-scale: 0.99;
  --press-dur: 150ms;
  --ease-smooth-out: cubic-bezier(0.22, 1, 0.36, 1);

  --chip: rgba(0, 0, 0, .04);
  --chip-hover: rgba(0, 0, 0, .06);
  --gray-hover: rgba(0, 0, 0, .02);
  --link: rgba(0, 83, 227, .8);
  --decline-bg: rgba(236, 74, 74, .1);
  --decline-bg-hover: rgba(236, 74, 74, .14);
  --decline-ink: #BD0F2C;
  --date-red: #EC4A4A;
  --card-shadow: 0 0 0 1px rgba(0,0,0,.04), 0 8px 32px -4px rgba(0,0,0,.06), 0 1px 3px 0 rgba(0,0,0,.04);
  --material-shadow: 0 4px 42px rgba(0,0,0,.06), 0 2px 6px rgba(0,0,0,.05), 0 0 0 1px rgba(0,0,0,.06);
  --cta-shadow: 0 1px 2px 0 rgba(0,0,0,.2);
  --divider: color-mix(in srgb, var(--stage-border) 70%, transparent);
}
html[data-theme="dark"] {
  --chip: rgba(255, 255, 255, .07);
  --chip-hover: rgba(255, 255, 255, .10);
  --gray-hover: rgba(255, 255, 255, .03);
  --link: rgba(122, 168, 255, .95);
  --decline-bg: rgba(236, 74, 74, .16);
  --decline-bg-hover: rgba(236, 74, 74, .22);
  --decline-ink: #ff9090;
  --date-red: #ff6b6b;
  --card-shadow: 0 1px 3px rgba(0,0,0,.04), inset 0 1px 0 rgba(255,255,255,.04), inset 0 0 0 1px rgba(196,196,196,.08);
  --material-shadow: 0 1px 3px rgba(0,0,0,.04), inset 0 1px 0 rgba(255,255,255,.04), inset 0 0 0 1px rgba(196,196,196,.08);
  --cta-shadow: 0 1px 2px 0 rgba(0,0,0,.4);
}

:where(.ev) button {
  font: inherit;
  padding: 0;
  border: 0;
  background: none;
  color: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
:where(.ev) button:focus-visible {
  outline: 2px solid var(--stage-accent);
  outline-offset: 2px;
}

.ev {
  width: 300px;
  border-radius: 24px;
  background: var(--stage-surface);
  box-shadow: var(--card-shadow);
  overflow: hidden;
  color: var(--stage-fg);
  -webkit-font-smoothing: antialiased;
}

/* Map header: full width, no padding, map at 50% */
.ev-map {
  position: relative;
  height: 104px;
  overflow: hidden;
}
.ev-map svg {
  display: block;
  width: 100%;
  height: 100%;
  opacity: .5;
}
.ev-pin {
  position: absolute;
  left: 50%;
  top: 42%;
  width: 14px;
  height: 14px;
  margin: -7px 0 0 -7px;
  border-radius: 50%;
  background: var(--date-red);
  box-shadow: 0 0 0 3px var(--stage-surface), 0 2px 6px rgba(0,0,0,.2);
}
.ev-pin::before {
  content: "";
  position: absolute;
  inset: -14px;
  border-radius: 50%;
  background: rgba(236, 74, 74, .16);
}

.ev-body {
  position: relative;
  padding: 0 24px 24px;
}

/* Apple Calendar style date tile */
.ev-date {
  position: relative;
  margin-top: -28px;
  width: 56px;
  height: 56px;
  border-radius: 12px;
  background: var(--stage-surface);
  box-shadow: var(--material-shadow);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.ev-date-day {
  font-size: 12px;
  line-height: 16px;
  font-weight: 400;
  color: var(--date-red);
}
.ev-date-num {
  font-size: 28px;
  line-height: 34px;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  margin-top: -4px;
}

.ev-title {
  margin: 12px 0 0;
  font-size: 28px;
  line-height: 34px;
  font-weight: 500;
  text-wrap: balance;
}

.ev-meta {
  margin-top: 8px;
  display: grid;
  gap: 4px;
}
.ev-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  line-height: 20px;
  color: var(--stage-muted);
}
.ev-row .hi { flex: none; }
.ev-row-text {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Directions link: Learn more hover */
.t-learn {
  flex: none;
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 13px;
  line-height: 20px;
  font-weight: 500;
  color: var(--link);
  padding: 2px 0;
}
.t-learn-chevron {
  display: inline-flex;
  transform: translateX(0);
  transition: transform var(--learn-out) var(--learn-ease);
}
.t-learn-arm {
  transform-box: view-box;
  transform-origin: 10px 8px;
  vector-effect: non-scaling-stroke;
  transition: transform var(--learn-out) var(--learn-ease);
}
@media (hover: hover) and (pointer: fine) { .t-learn:hover .t-learn-chevron { transform: translateX(var(--learn-shift)); transition-duration: var(--learn-in); } }
@media (hover: hover) and (pointer: fine) { .t-learn:hover .t-learn-arm { transition-duration: var(--learn-in); } }
@media (hover: hover) and (pointer: fine) { .t-learn:hover .t-learn-arm-top { transform: rotate(var(--learn-spread)); } }
@media (hover: hover) and (pointer: fine) { .t-learn:hover .t-learn-arm-bot { transform: rotate(calc(var(--learn-spread) * -1)); } }

.ev-divider {
  height: 1px;
  margin: 12px 0 4px;
  background: linear-gradient(90deg, transparent, var(--divider) 20%, var(--divider) 80%, transparent);
}

/* Attendees accordion */
.t-acc-head {
  display: flex;
  align-items: center;
  gap: 8px;
  width: calc(100% + 24px);
  margin: 0 -12px;
  padding: 8px 12px;
  border-radius: 12px;
  text-align: left;
  font-size: 13px;
  line-height: 20px;
  transition: background-color var(--press-dur) var(--ease-smooth-out);
}
@media (hover: hover) and (pointer: fine) { .t-acc-head:hover { background: var(--gray-hover); } }
.ev-acc-label { flex: 1; min-width: 0; color: var(--stage-fg); }
.ev-acc-count {
  flex: none;
  color: var(--stage-muted);
  font-variant-numeric: tabular-nums;
}
.t-acc-chevron { color: var(--stage-muted); }

.t-acc-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows var(--acc-collapse) var(--acc-ease);
}
.t-acc[data-open="true"] .t-acc-panel {
  grid-template-rows: 1fr;
  transition: grid-template-rows var(--acc-expand) var(--acc-ease);
}
.t-acc-panel-inner {
  overflow: hidden;
  opacity: 0;
  filter: blur(2px);
  transition:
    opacity var(--acc-collapse) var(--acc-ease),
    filter var(--acc-collapse) var(--acc-ease);
}
.t-acc[data-open="true"] .t-acc-panel-inner {
  opacity: 1;
  filter: blur(0);
  transition:
    opacity var(--acc-expand) var(--acc-ease),
    filter var(--acc-expand) var(--acc-ease);
}
.t-acc-chevron {
  display: inline-flex;
  flex: none;
  transform: scaleY(1);
  transform-origin: center;
  transition: transform var(--acc-chevron) var(--acc-ease);
}
.t-acc-chevron path { vector-effect: non-scaling-stroke; }
.t-acc[data-open="true"] .t-acc-chevron { transform: scaleY(-1); }

.ev-people {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 0 4px;
}
.t-avatar-group {
  display: flex;
  flex: none;
  padding-left: 2px;
}
.t-avatar {
  display: inline-flex;
  position: relative;
  transform-origin: center;
  transform: translateY(var(--shift, 0px)) scale(var(--scale-active, 1));
  transition: transform var(--avatar-dur) var(--avatar-ease-in);
  will-change: transform;
}
.t-avatar + .t-avatar { margin-left: -6px; }
.t-avatar .t-av {
  box-shadow: 0 0 0 2px var(--stage-surface), inset 0 0 0 1px rgba(0,0,0,.02);
}
.ev-people-text {
  flex: 1;
  min-width: 0;
  font-size: 12px;
  line-height: 16px;
  color: var(--stage-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Actions */
.ev-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}
.btn {
  height: 36px;
  border-radius: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 12px;
  font-size: 13px;
  line-height: 20px;
  font-weight: 500;
  white-space: nowrap;
  transition:
    transform var(--press-dur) var(--ease-smooth-out),
    background-color var(--decline-dur) var(--ease-smooth-out),
    color var(--decline-dur) var(--ease-smooth-out);
}
.btn:is(:active,.is-pressed) {
  transform: scale(var(--press-scale));
  transition-duration: 0ms;
}
:where(.ev) .btn-primary {
  flex: 1;
  min-width: 0;
  background: var(--stage-accent);
  color: var(--stage-on-accent);
  box-shadow: var(--cta-shadow);
}
@media (hover: hover) and (pointer: fine) { :where(.ev) .btn-primary:hover {
  background: color-mix(in srgb, var(--stage-accent) 88%, var(--stage-bg));
} }
:where(.ev) .btn-secondary {
  flex: none;
  background: var(--chip);
  color: var(--stage-fg);
}
@media (hover: hover) and (pointer: fine) { :where(.ev) .btn-secondary:hover { background: var(--chip-hover); } }
:where(.ev) .btn-secondary[data-declined="true"] {
  background: var(--decline-bg);
  color: var(--decline-ink);
}
@media (hover: hover) and (pointer: fine) { :where(.ev) .btn-secondary[data-declined="true"]:hover { background: var(--decline-bg-hover); } }

/* Text states swap (Join call) */
.t-text-swap {
  display: inline-block;
  transform: translateY(0);
  filter: blur(0);
  opacity: 1;
  transition:
    transform var(--text-swap-dur) var(--text-swap-ease),
    filter    var(--text-swap-dur) var(--text-swap-ease),
    opacity   var(--text-swap-dur) var(--text-swap-ease);
  will-change: transform, filter, opacity;
}
.t-text-swap.is-exit {
  transform: translateY(calc(var(--text-swap-translate-y) * -1));
  filter: blur(var(--text-swap-blur));
  opacity: 0;
}
.t-text-swap.is-enter-start {
  transform: translateY(var(--text-swap-translate-y));
  filter: blur(var(--text-swap-blur));
  opacity: 0;
  transition: none;
}

/* Text morph (Decline → Declined) */
.t-morph { white-space: nowrap; }
.t-morph-swap {
  display: inline-grid;
  vertical-align: bottom;
  justify-items: start;
  transition: width var(--text-morph-resize-dur) var(--text-morph-ease);
}
.t-morph-swap > span {
  grid-area: 1 / 1;
  white-space: pre;
  transition:
    opacity var(--text-morph-dur) var(--text-morph-ease),
    filter  var(--text-morph-dur) var(--text-morph-ease);
}
.t-morph-new {
  opacity: 0;
  filter: blur(var(--text-morph-blur));
}
.t-morph-swap.is-morphing .t-morph-old {
  opacity: 0;
  filter: blur(var(--text-morph-blur));
}
.t-morph-swap.is-morphing .t-morph-new {
  opacity: 1;
  filter: blur(0);
}

@media (prefers-reduced-motion: reduce) {
  .t-acc-panel, .t-acc-panel-inner, .t-acc-chevron { transition: none !important; }
  .t-avatar { transition: none !important; transform: none !important; }
  .t-text-swap { transition: none !important; }
  .t-morph-swap, .t-morph-swap > span { transition: none !important; }
  .t-learn-chevron, .t-learn-arm { transition: none !important; }
  .btn:is(:active,.is-pressed) { transform: none; }
}

