/* Avatars: avvvatars colors (MIT, github.com/nusu/avvvatars) */
.t-av{display:inline-grid;place-items:center;flex:none;box-sizing:border-box;width:var(--av-size,24px);height:var(--av-size,24px);border-radius:50%;background:color-mix(in srgb,var(--av-bg) 70%,transparent);color:var(--av-fg);font-size:max(10px,calc(var(--av-size,24px) * .4));font-weight:500;line-height:1;letter-spacing:0;box-shadow:inset 0 0 0 1px rgba(0,0,0,.02);user-select:none}
html[data-theme="dark"] .t-av{background:color-mix(in srgb,var(--av-fg) 30%,#202020);color:var(--av-bg);box-shadow:inset 0 0 0 1px rgba(255,255,255,.04)}
.t-av[data-empty]{background:rgba(0,0,0,.06);color:var(--stage-muted,#8a8a8a)}
html[data-theme="dark"] .t-av[data-empty]{background:rgba(255,255,255,.08);color:var(--stage-muted,#8a8a8a)}
.t-av[data-empty] svg{width:55%;height:55%}

/* Touch: controls press in full on a tap, never select their label, and hover only applies with a mouse. */
:where(button,[role="button"],[role="tab"],[role="menuitem"],[role="menuitemcheckbox"],[role="menuitemradio"],[role="option"],[role="switch"],summary,.t-pressable){-webkit-tap-highlight-color:transparent;touch-action:manipulation;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
/* end touch */

