(function () {
  const rootEl = document.documentElement;
  const ms = (name, fb) => {
    const v = parseFloat(getComputedStyle(rootEl).getPropertyValue(name));
    return Number.isFinite(v) ? v : (fb || 0);
  };

  /* Accordion */
  const acc = document.querySelector('.ev .t-acc');
  const head = acc.querySelector('.t-acc-head');
  head.addEventListener('click', () => {
    const open = acc.getAttribute('data-open') === 'true';
    acc.setAttribute('data-open', String(!open));
    head.setAttribute('aria-expanded', String(!open));
  });

  /* Avatar group hover */
  const group = document.querySelector('.ev .t-avatar-group');
  const avatars = Array.from(group.querySelectorAll('.t-avatar'));
  const ease = (name, fb) => getComputedStyle(rootEl).getPropertyValue(name).trim() || fb;
  function setShifts(activeIdx, phase) {
    const lift = ms('--avatar-lift', -4);
    const falloff = ms('--avatar-falloff', 0.45);
    const scale = ms('--avatar-scale', 1.05);
    const tf = phase === 'out'
      ? ease('--avatar-ease-out', 'cubic-bezier(0.34, 3.85, 0.64, 1)')
      : ease('--avatar-ease-in', 'cubic-bezier(0.22, 1, 0.36, 1)');
    avatars.forEach((el, i) => {
      el.style.transitionTimingFunction = tf;
      if (activeIdx == null) {
        el.style.setProperty('--shift', '0px');
        el.style.setProperty('--scale-active', '1');
        return;
      }
      const d = Math.abs(i - activeIdx);
      el.style.setProperty('--shift', (lift * Math.pow(falloff, d)).toFixed(3) + 'px');
      el.style.setProperty('--scale-active', i === activeIdx ? String(scale) : '1');
    });
  }
  avatars.forEach((el, i) => el.addEventListener('mouseenter', () => setShifts(i, 'in')));
  group.addEventListener('mouseleave', () => setShifts(null, 'out'));

  /* Text morph: Decline ↔ Declined */
  function morphText(el, next) {
    const prev = el.dataset.text ?? el.textContent;
    if (prev === next) return;
    el.dataset.text = next;
    clearTimeout(el._morphTimer);
    let a = 0;
    while (a < prev.length && a < next.length && prev[a] === next[a]) a++;
    let b = 0;
    while (b < prev.length - a && b < next.length - a &&
           prev[prev.length - 1 - b] === next[next.length - 1 - b]) b++;
    const swap = document.createElement('span');
    swap.className = 't-morph-swap';
    const out = document.createElement('span');
    out.className = 't-morph-old';
    out.setAttribute('aria-hidden', 'true');
    out.textContent = prev.slice(a, prev.length - b);
    const inn = document.createElement('span');
    inn.className = 't-morph-new';
    inn.textContent = next.slice(a, next.length - b);
    swap.append(out, inn);
    el.textContent = '';
    el.append(next.slice(0, a), swap, next.slice(next.length - b));
    swap.style.width = out.getBoundingClientRect().width + 'px';
    void swap.offsetWidth;
    swap.classList.add('is-morphing');
    swap.style.width = inn.getBoundingClientRect().width + 'px';
    el._morphTimer = setTimeout(() => {
      el.textContent = next;
    }, Math.max(ms('--text-morph-dur'), ms('--text-morph-resize-dur')) + 40);
  }

  const decline = document.getElementById('ev-decline');
  const declineLabel = decline.querySelector('.t-morph');
  decline.addEventListener('click', () => {
    const declined = decline.getAttribute('data-declined') !== 'true';
    decline.setAttribute('data-declined', String(declined));
    decline.setAttribute('aria-pressed', String(declined));
    morphText(declineLabel, declined ? 'Declined' : 'Decline');
  });

  /* Text states swap: Join call → Connecting… → Join call */
  const join = document.getElementById('ev-join');
  const joinLabel = join.querySelector('.t-text-swap');
  let busy = false;
  function swapText(el, next) {
    const dur = ms('--text-swap-dur', 150);
    el.classList.add('is-exit');
    setTimeout(() => {
      el.textContent = next;
      el.classList.remove('is-exit');
      el.classList.add('is-enter-start');
      void el.offsetHeight;
      el.classList.remove('is-enter-start');
    }, dur);
  }
  join.addEventListener('click', () => {
    if (busy) return;
    busy = true;
    swapText(joinLabel, 'Connecting…');
    setTimeout(() => {
      swapText(joinLabel, 'Join call');
      setTimeout(() => { busy = false; }, ms('--text-swap-dur', 150));
    }, 1800);
  });
})();

